// Package fakecodex is a `codex app-server` stand-in for tests. It speaks
// the JSON-RPC shapes of the installed app-server (0.159), as generated by
// `codex app-server generate-json-schema`: initialize, thread/start,
// thread/resume, turn/start, turn/steer and turn/interrupt, the item and
// turn/completed notifications, and the command and file-change approval
// requests.
//
// A test package calls [RunIfFake] first in its TestMain, then [Install] to
// get a "codex" binary: a script that re-runs the test binary in fake mode.
//
// A turn says "working on it", then, when the file "approval" in the fake's
// directory names one, asks for approval of a command ("command") or a file
// change ("file") and waits for the answer. An accepted step runs (the file
// "ran" is written); a declined one is reported declined, and the fake waits
// up to two seconds for a turn/steer. The turn then says "done here" and
// completes.
//
// Under its directory every process N writes call<N>.argv (one per line),
// call<N>.cwd, call<N>.env (the environment) and call<N>.rpc (every line it
// read). The answer to an approval is written to "answer", a steer's text to
// "steer".
package fakecodex

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"testing"
	"time"
)

const envDir = "NACRE_FAKE_CODEX_DIR"

// ThreadID is the thread a fake thread/start creates.
const ThreadID = "019a0000-0000-7000-8000-00000000c0de"

// Install writes a codex stand-in and returns its path and its record
// directory.
func Install(t testing.TB) (bin, dir string) {
	t.Helper()
	exe, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	dir = t.TempDir()
	bin = filepath.Join(dir, "codex")
	script := fmt.Sprintf("#!/bin/sh\n%s=%s exec %s \"$@\"\n", envDir, shellQuote(dir), shellQuote(exe))
	if err := os.WriteFile(bin, []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	return bin, dir
}

func shellQuote(s string) string { return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'" }

// RunIfFake runs the fake and exits when this process was started as one.
func RunIfFake() {
	dir := os.Getenv(envDir)
	if dir == "" {
		return
	}
	os.Exit(run(dir))
}

type message struct {
	ID     json.RawMessage `json:"id,omitempty"`
	Method string          `json:"method,omitempty"`
	Params json.RawMessage `json:"params,omitempty"`
	Result json.RawMessage `json:"result,omitempty"`
}

type fake struct {
	dir   string
	n     int
	outMu sync.Mutex
	rpc   *os.File
	// answers carries responses to the fake's own requests.
	answers chan message
	steered chan struct{}
	turns   int
}

func run(dir string) int {
	matches, _ := filepath.Glob(filepath.Join(dir, "call*.argv"))
	f := &fake{dir: dir, n: len(matches), answers: make(chan message, 4), steered: make(chan struct{}, 4)}
	_ = os.WriteFile(f.path("argv"), []byte(strings.Join(os.Args[1:], "\n")+"\n"), 0o644)
	wd, _ := os.Getwd()
	_ = os.WriteFile(f.path("cwd"), []byte(wd+"\n"), 0o644)
	_ = os.WriteFile(f.path("env"), []byte(strings.Join(os.Environ(), "\n")+"\n"), 0o644)
	if len(os.Args) < 2 || os.Args[1] != "app-server" {
		fmt.Fprintln(os.Stderr, "fakecodex: only app-server is faked")
		return 2
	}
	rpc, err := os.Create(f.path("rpc"))
	if err != nil {
		return 1
	}
	defer rpc.Close()
	f.rpc = rpc

	br := bufio.NewReaderSize(os.Stdin, 1024*1024)
	for {
		line, err := br.ReadBytes('\n')
		if len(strings.TrimSpace(string(line))) > 0 {
			_, _ = rpc.Write(line)
			var m message
			if json.Unmarshal(line, &m) == nil {
				f.handle(m)
			}
		}
		if err != nil {
			return 0
		}
	}
}

func (f *fake) path(name string) string {
	return filepath.Join(f.dir, "call"+strconv.Itoa(f.n)+"."+name)
}

func (f *fake) send(v any) {
	line, _ := json.Marshal(v)
	f.outMu.Lock()
	defer f.outMu.Unlock()
	os.Stdout.Write(append(line, '\n'))
}

func (f *fake) reply(id json.RawMessage, result any) {
	f.send(map[string]any{"id": id, "result": result})
}

func (f *fake) notify(method string, params any) {
	f.send(map[string]any{"method": method, "params": params})
}

func thread(id string) map[string]any {
	return map[string]any{"id": id, "status": map[string]string{"type": "idle"}, "turns": []any{}}
}

func (f *fake) handle(m message) {
	if m.Method == "" {
		f.answers <- m // an answer to the fake's approval request
		return
	}
	var p map[string]any
	_ = json.Unmarshal(m.Params, &p)
	switch m.Method {
	case "initialize":
		f.reply(m.ID, map[string]any{"userAgent": "fakecodex/0.159.2", "codexHome": f.dir, "platformFamily": "unix", "platformOs": "macos"})
	case "initialized":
	case "thread/start":
		f.reply(m.ID, map[string]any{"thread": thread(ThreadID), "model": "gpt-fake", "modelProvider": "openai", "cwd": p["cwd"], "approvalPolicy": p["approvalPolicy"], "approvalsReviewer": "user", "sandbox": map[string]string{"type": "workspaceWrite"}})
		f.notify("thread/started", map[string]any{"thread": thread(ThreadID)})
	case "thread/resume":
		id, _ := p["threadId"].(string)
		f.reply(m.ID, map[string]any{"thread": thread(id), "model": "gpt-fake", "modelProvider": "openai", "cwd": p["cwd"], "approvalPolicy": p["approvalPolicy"], "approvalsReviewer": "user", "sandbox": map[string]string{"type": "workspaceWrite"}})
	case "turn/start":
		f.turns++
		threadID, _ := p["threadId"].(string)
		turnID := "turn_" + strconv.Itoa(f.n) + "_" + strconv.Itoa(f.turns)
		f.reply(m.ID, map[string]any{"turn": map[string]any{"id": turnID, "status": "inProgress", "items": []any{}}})
		go f.turn(threadID, turnID)
	case "turn/steer":
		if in, ok := p["input"].([]any); ok && len(in) > 0 {
			if first, ok := in[0].(map[string]any); ok {
				text, _ := first["text"].(string)
				_ = os.WriteFile(filepath.Join(f.dir, "steer"), []byte(text), 0o644)
			}
		}
		turnID, _ := p["expectedTurnId"].(string)
		f.reply(m.ID, map[string]any{"turnId": turnID})
		f.steered <- struct{}{}
	case "turn/interrupt":
		f.reply(m.ID, map[string]any{})
		threadID, _ := p["threadId"].(string)
		turnID, _ := p["turnId"].(string)
		f.notify("turn/completed", map[string]any{"threadId": threadID, "turn": map[string]any{"id": turnID, "status": "interrupted", "items": []any{}}})
	default:
		f.send(map[string]any{"id": m.ID, "error": map[string]any{"code": -32601, "message": "fakecodex: no " + m.Method}})
	}
}

func (f *fake) item(threadID, turnID, method string, item map[string]any) {
	f.notify(method, map[string]any{"threadId": threadID, "turnId": turnID, "item": item, "startedAtMs": 1, "completedAtMs": 2})
}

func (f *fake) turn(threadID, turnID string) {
	f.notify("turn/started", map[string]any{"threadId": threadID, "turn": map[string]any{"id": turnID, "status": "inProgress", "items": []any{}}})
	f.item(threadID, turnID, "item/completed", map[string]any{"id": "msg_1", "type": "agentMessage", "text": "working on it"})

	kind, _ := os.ReadFile(filepath.Join(f.dir, "approval"))
	switch strings.TrimSpace(string(kind)) {
	case "command":
		cmd := map[string]any{"id": "cmd_1", "type": "commandExecution", "command": "/bin/zsh -lc 'tailscale file cp app.apk pixel:'", "cwd": "/tmp", "status": "inProgress", "commandActions": []any{}}
		f.item(threadID, turnID, "item/started", cmd)
		f.approve(threadID, turnID, "item/commandExecution/requestApproval", map[string]any{
			"threadId": threadID, "turnId": turnID, "itemId": "cmd_1", "startedAtMs": 1,
			"command": "/bin/zsh -lc 'tailscale file cp app.apk pixel:'", "cwd": "/tmp", "reason": "needs network access outside the sandbox",
		}, cmd)
	case "file":
		change := map[string]any{"id": "fc_1", "type": "fileChange", "status": "inProgress", "changes": []any{map[string]any{"path": "/etc/hosts", "kind": map[string]string{"type": "update"}, "diff": ""}}}
		f.item(threadID, turnID, "item/started", change)
		f.approve(threadID, turnID, "item/fileChange/requestApproval", map[string]any{
			"threadId": threadID, "turnId": turnID, "itemId": "fc_1", "startedAtMs": 1, "reason": "writes outside the workspace",
		}, change)
	}

	f.item(threadID, turnID, "item/completed", map[string]any{"id": "msg_2", "type": "agentMessage", "text": "done here"})
	f.notify("turn/completed", map[string]any{"threadId": threadID, "turn": map[string]any{"id": turnID, "status": "completed", "items": []any{}}})
}

// approve asks for approval of item and reports the step run or declined.
func (f *fake) approve(threadID, turnID, method string, params map[string]any, item map[string]any) {
	f.send(map[string]any{"id": 0, "method": method, "params": params})
	ans := <-f.answers
	_ = os.WriteFile(filepath.Join(f.dir, "answer"), ans.Result, 0o644)
	var r struct {
		Decision string `json:"decision"`
	}
	_ = json.Unmarshal(ans.Result, &r)
	if r.Decision == "accept" || r.Decision == "acceptForSession" {
		_ = os.WriteFile(filepath.Join(f.dir, "ran"), []byte("yes\n"), 0o644)
		item["status"] = "completed"
		if item["type"] == "commandExecution" {
			item["aggregatedOutput"] = "sent\n"
			item["exitCode"] = 0
		}
	} else {
		item["status"] = "declined"
		select {
		case <-f.steered:
		case <-time.After(2 * time.Second):
		}
	}
	f.item(threadID, turnID, "item/completed", item)
}
